  protected async saveInline(claim: ClaimView): Promise<void> {
    this.claimError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const amount = (this.inlineAmounts()[claim.id] ?? '').trim();
    if (!AMOUNT.test(amount)) {
      this.claimError.set({ id: claim.id, message: 'Type an amount with up to two decimals; below 0.00 only for a correction.' });
      return;
    }
    const me = this.session.user()?.trim();
    const period = periodOn(this.periods(), claim.dueBy);
    try {
      const saved = await this.api.edit(sheet, claim.id, { amount, date: claim.date, note: claim.note, corrects: claim.corrects ?? null, ref: claim.ref ?? '' });
      this.saved.emit(saved);
      this.inlineAmounts.update((amounts) => ({ ...amounts, [claim.id]: '' }));
      // the save released this user's lock, so an editor left open on the claim is closed
      if (this.editing() === claim.id) this.reset();
    } catch (e) {
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      this.claimError.set({
        id: claim.id,
        message: status === 403
          ? 'Your role is not allowed to edit a claim.'
          : claim.status !== 'DRAFT'
            ? `A ${claim.status} claim cannot be edited; void it and add a new one.`
            : period?.closed
              ? `Period ${period.name} is closed, so its claims cannot be edited.`
              : status === 423 || (claim.lockedBy !== null && claim.lockedBy !== me)
                ? this.lockedMessage(claim.lockedBy)
                : amount.startsWith('-')
                  ? `The claim could not be saved: a correction (an amount below 0.00) must name a SETTLED claim of ${this.personName()}.`
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.move(sheetId, SignedIn.name(user), claimId, ClaimStatus.SETTLED));
    }

    /** Settle the selected claims together, in list order; those that cannot be settled are refused. */
    @PostMapping("/claims/settle")
    public BulkSettleView settleAll(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid BulkSettleForm form) {
        BulkMoveService.Result result = bulk.settle(sheetId, SignedIn.name(user), form.claimIds());
        return new BulkSettleView(result.moved().stream().map(ClaimView::of).toList(), result.refused());
    }

    /** Approve a PENDING claim, settling it; only a steward, and not the user who opened it. */
    @PostMapping("/claims/{claimId}/approve")
    public ClaimView approve(
    }

    /** Open the selected claims, each as its Open button would. */
    public Result open(String sheetId, String user, Collection<Long> claimIds) {
        return move(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /**
     * Settle the selected claims, each as its Settle button would: a claim a clerk sends PENDING
     * counts as settled.
     */
    public Result settle(String sheetId, String user, Collection<Long> claimIds) {
        return move(sheetId, user, claimIds, ClaimStatus.SETTLED);
    }

    private Result move(String sheetId, String user, Collection<Long> claimIds, ClaimStatus next) {
        Set<Long> selected = new HashSet<>(claimIds);
        if (Role.VIEWER.equals(roles.roleOf(sheetId, user)) || sheets.archived(sheetId)) {
            return new Result(List.of(), selected.size());
        }
        List<Long> ordered = new ArrayList<>();
        List<Claim> sheetClaims = claims.list(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId().equals(person.getId()) && selected.contains(claim.getId())) {
                    ordered.add(claim.getId());
                }
            }
        }
        List<Claim> moved = new ArrayList<>();
        for (Long id : ordered) {
            try {
                moved.add(claims.move(sheetId, user, id, next));
            } catch (ResponseStatusException refused) {
                // left as it is: its move wrote nothing
            }
        }
        return new Result(moved, selected.size() - moved.size());
    }
}

