unlock(sheet: string, id: number): Promise<ClaimView> {
  return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/claims/${id}/unlock`, null));
}

/**
 * Move a claim's status; refused (409) when its status does not allow the move, or when the user
 * settling or approving it is the one who opened it, and (403) when approving or rejecting it is
 * not a steward. A reject carries its reason. Re-settling is a steward's (403 otherwise), of a
 * SETTLED claim (409 otherwise). A void carries the reason chosen from the sheet's list (409 when
 * the list is not empty and none, or one not on it, is given).
 */
act(sheet: string, id: number, action: ClaimAction, reason?: string): Promise<ClaimView> {
  const body = action === 'reject' ? { reason: reason ?? '' } : action === 'void' ? { reason: reason || null } : null;
protected async act(claim: ClaimView, action: ClaimAction): Promise<void> {
  this.claimError.set(null);
  const sheet = this.session.sheet();
  if (!sheet) return;
  const reason = action === 'void'
    ? (this.voidReasonsChosen()[claim.id] ?? '')
    : (this.rejectReasons()[claim.id] ?? '').trim();
  if (action === 'reject' && reason === '') {
    this.claimError.set({ id: claim.id, message: 'Type a reason to reject the claim.' });
    return;
  }
  if (action === 'void' && reason === '' && this.voidReasons.list().length > 0) {
    this.claimError.set({ id: claim.id, message: 'Choose a reason from the list to void the claim.' });
    return;
  }
  try {
    this.saved.emit(await this.api.act(sheet, claim.id, action, reason));
    if (action === 'reject') this.rejectReasons.update((reasons) => ({ ...reasons, [claim.id]: '' }));
  } catch (e) {
    const mine = claim.openedBy === this.session.user()?.trim();
    const own = (action === 'settle' && claim.status === 'OPEN' && mine)
      || (action === 'approve' && claim.status === 'PENDING' && mine);
    const unproved = e instanceof HttpErrorResponse && e.status === 409 && claim.proofs === 0
      && ((action === 'settle' && claim.status === 'OPEN') || (action === 'approve' && claim.status === 'PENDING'));
    const unnoted = e instanceof HttpErrorResponse && e.status === 409 && action === 'open'
      && claim.status === 'DRAFT' && (claim.note ?? '').trim() === '';
    const steward = e instanceof HttpErrorResponse && e.status === 403
      && (((action === 'approve' || action === 'reject') && claim.status === 'PENDING')
        || ((action === 'resettle' || action === 'void') && claim.status === 'SETTLED'));
    const forbidden = e instanceof HttpErrorResponse && e.status === 403 && !steward
      && (action === 'open' || action === 'settle' || action === 'void');
    const lateVoid = e instanceof HttpErrorResponse && e.status === 409
      && action === 'void' && claim.status === 'SETTLED';
    this.claimError.set({
      id: claim.id,
      message: forbidden
        ? `Your role is not allowed to ${action} a claim.`
        : action === 'settle' && deferred(claim, this.session.today() ?? '')
        ? `The claim is deferred until ${claim.deferredUntil}, so it cannot be settled before then.`
        : own
          ? `You opened this claim, so someone else must ${action} it.`
          : unproved
            ? `The claim's due is above the proof threshold, so it needs a proof before it can be ${PAST[action]}.`
          : unnoted
            ? "The claim's due is above the note threshold, so it needs a note before it can be opened."
          : steward
            ? `Only a steward can ${action === 'resettle' ? 're-settle' : action} a ${claim.status} claim.`
          : lateVoid
            ? 'A SETTLED claim can only be voided within 7 days of its settlement, outside a closed period.'
            : `A ${claim.status} claim cannot be ${PAST[action]}.`,
    });
note: string;
status: ClaimStatus;
/**
 * The number given when the claim was opened: sheet-wide (e.g. "3"), or under period numbering
 * within its period (e.g. "P1-2", or "X-1" in no period); null while DRAFT, and kept once VOID.
 */
number: string | null;
/**
 * The due fixed when the claim was settled, with two decimals; null when it is not fixed (not
 * settled, or the grade had no rate then), so its due follows the current rate.
 */
settledDue: string | null;
/** The user who opened the claim; null until it is opened. The opener cannot settle it. */
openedBy: string | null;
/** Whether the claim is bound by its person's last statement to the figure it had then. */
stated: boolean;
/** The figure the statement bound the claim to, with two decimals; null when unbound, or when it was n/a. */
statedDue: string | null;
/** The number of the SETTLED claim this one corrects; null unless it is a correction. */
corrects: string | null;
/** The claim's external reference; null when it has none. */
ref: string | null;
/** The claim's tags, sorted (trimmed, lower case, no repeats); empty (or absent, as kept by an old snapshot) for none. */
tags?: string[] | null;
/** Every tag the claim has ever carried, sorted; empty (or absent, as kept by an old snapshot) for none. */
tagsUsed?: string[] | null;
/** The claim's status log, oldest first: one line per status it has had. */
log: ClaimLogLine[];
/** yyyy-mm-dd: the date the claim is deferred until; null when it was never deferred. */
deferredUntil: string | null;
/** How many proofs the claim has. Above the proof threshold, a claim with none cannot be settled or approved. */
   * and the number of the claim it was split from (null unless it was split off another), and the user whose open
   * editor locks it (null when none does), and the last day it was reminded (null when never), and its
   * external reference (null when it has none), and its tags, sorted, and every tag it has ever carried, sorted,
   * and the reason it was voided with (null when none), and its comments, oldest first.
   */
  public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note, ClaimStatus status,
          String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, List<LogLineView> log,
          LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn,
          String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<CommentView> comments) {

      public static ClaimView of(Claim claim) {
          return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                  claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                  claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                  claim.getOpenedBy(), claim.isStated(),
                  claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                  claim.getCorrects(), claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil(),
                  claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(), claim.getRemindedOn(),
                  claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(),
                  claim.getComments().stream().map(CommentView::of).toList());
      }
  }

  /** A line of a claim's status log; the due with two decimals, or n/a. */
  public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {

