                || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(claim.getDate(), today))) {
            continue;
        }
        BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
        if (figure != null) {
            totals.merge(person.getId(), figure, BigDecimal::add);
        }
    }
    return totals;
}

